 * SMILES tokenizer / validator for a strict subset:
 *
 *  - Organic-subset atoms:   B C N O P S F Cl Br I
 *  - Aromatic atoms:         b c n o p s
 *  - Bonds:                  - = # :
 *  - Branch parentheses:     ( )
 *  - Ring closures:          digits 1-9 and two-digit %nn
 *  - Bracket atoms:          [Element], [ElementHn], with optional +/-
 *                            charge (e.g. [NH4+]) — nothing else allowed.
 */

export type TokenType = 'atom' | 'bond' | 'lparen' | 'rparen' | 'ring';

export interface Token {
  type: TokenType;
  /** Exact source text of the token. */
  value: string;
}

export interface ValidationResult {
  ok: boolean;
  error?: string;
}

export class SMILESError extends Error {}

const ORGANIC = new Set(['B', 'C', 'N', 'O', 'P', 'S', 'F', 'Cl', 'Br', 'I']);
const AROMATIC = new Set(['b', 'c', 'n', 'o', 'p', 's']);
const BONDS = new Set(['-', '=', '#', ':']);

const BRACKET_RE = /^([A-Z][a-z]?)(H\d*)?([+-]\d*)?$/;

/** Lexical analysis. Throws SMILESError on malformed input. */
function lex(s: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < s.length) {
    // Two-letter organic atoms first (Cl, Br).
    const two = s.slice(i, i + 2);
    if (ORGANIC.has(two)) {
      tokens.push({ type: 'atom', value: two });
      i += 2;
      continue;
    }

    const ch = s[i]!;

    if (ORGANIC.has(ch) || AROMATIC.has(ch)) {
      tokens.push({ type: 'atom', value: ch });
      i += 1;
      continue;
    }

    if (BONDS.has(ch)) {
      tokens.push({ type: 'bond', value: ch });
      i += 1;
      continue;
    }

    if (ch === '(') {
      tokens.push({ type: 'lparen', value: ch });
      i += 1;
      continue;
    }

    if (ch === ')') {
      tokens.push({ type: 'rparen', value: ch });
      i += 1;
      continue;
    }

    if (ch >= '1' && ch <= '9') {
      tokens.push({ type: 'ring', value: ch });
      i += 1;
      continue;
    }

    if (ch === '%') {
      const digits = s.slice(i + 1, i + 3);
      if (!/^\d{2}$/.test(digits)) {
        throw new SMILESError(
          `malformed ring closure '%': expected exactly two digits after '%' at position ${i}`,
        );
      }
      tokens.push({ type: 'ring', value: '%' + digits });
      i += 3;
      continue;
    }

    if (ch === '[') {
      const close = s.indexOf(']', i);
      if (close === -1) {
        throw new SMILESError(`unterminated bracket atom starting at position ${i}`);
      }
      const inner = s.slice(i + 1, close);
      if (!BRACKET_RE.test(inner)) {
        throw new SMILESError(
          `invalid bracket atom '[${inner}]' at position ${i}: expected element, optional H count, optional +/- charge`,
        );
      }
      tokens.push({ type: 'atom', value: `[${inner}]` });
      i = close + 1;
      continue;
    }

    throw new SMILESError(`unexpected character '${ch}' at position ${i}`);
  }

  return tokens;
}

/** Structural checks over the token stream. */
function check(tokens: Token[]): ValidationResult {
  if (tokens.length === 0) {
    return { ok: false, error: 'empty SMILES string' };
  }

  const openParens = new Set<number>(); // indices of unmatched '('
  const openRings = new Set<number>();
  let pendingBond = false;

  for (let idx = 0; idx < tokens.length; idx++) {
    const t = tokens[idx]!;
    switch (t.type) {
      case 'atom':
        pendingBond = false;
        break;

      case 'ring': {
        pendingBond = false;
        const n = parseInt(t.value.replace('%', ''), 10);
        if (openRings.has(n)) {
          openRings.delete(n);
        } else {
          openRings.add(n);
        }
        break;
      }

      case 'bond':
        if (!pendingBond && idx === 0) {
          return { ok: false, error: 'SMILES cannot begin with a bond' };
        }
        if (pendingBond) {
          return { ok: false, error: 'consecutive bonds are not allowed' };
        }
        pendingBond = true;
        break;

      case 'lparen': {
        const prev = idx > 0 ? tokens[idx - 1] : undefined;
        const okPrev =
          prev !== undefined &&
          (prev.type === 'atom' || prev.type === 'ring' || prev.type === 'rparen');
        if (!okPrev) {
          return { ok: false, error: "unexpected '(' — a branch must follow an atom or ring closure" };
        }
        openParens.add(idx);
        break;
      }

      case 'rparen': {
        if (openParens.size === 0) {
          return { ok: false, error: "unbalanced parenthesis: unexpected ')'" };
        }
        const prev = tokens[idx - 1];
        if (prev!.type === 'lparen') {
          return { ok: false, error: "empty branch '()' is not allowed" };
        }
        if (prev!.type === 'bond') {
          return { ok: false, error: 'a bond must connect to an atom before ")"' };
        }
        // Remove the most recently opened paren.
        let maxIdx = -1;
        for (const p of openParens) if (p > maxIdx) maxIdx = p;
        openParens.delete(maxIdx);
        break;
      }
    }
  }

  if (pendingBond) {
    return { ok: false, error: 'trailing bond: a bond must be followed by an atom or ring closure' };
  }
  if (openParens.size > 0) {
    const n = openParens.size;
    return {
      ok: false,
      error: `unbalanced parenthesis: missing ${n} closing parenthes${n === 1 ? 'is' : 'es'} ')'`,
    };
  }
  if (openRings.size > 0) {
    const list = [...openRings].sort((a, b) => a - b).join(', ');
    return { ok: false, error: `unclosed ring bond(s): ${list}` };
  }

  return { ok: true };
}

/**
 * Tokenize a SMILES string.
 * Throws SMILESError for lexically invalid input.
 */
export function tokenize(s: string): Token[] {
  return lex(s);
}

/** Validate a SMILES string; returns { ok: true } or { ok: false, error }. */
export function validate(s: string): ValidationResult {
  try {
    return check(lex(s));
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : String(e) };
  }
}
